import { ActionDefinition } from '../../../Action'
import { BooleanColumn, StringColumn, DocumentIdColumn, TableNameColumn } from '../../../../db'

export const deleteAttachment = ActionDefinition({
    $id: 'bdc2a0170f973300dfd3694e68767e47',
    name: 'Delete Attachment',
    description:
        'Deletes one or more attachment(s) associated with the record. You could delete a single attachment by providing File Name input field .You could also delete all the attachments bound to the record by using Delete All Attachment checbox. Either File Name input field or Delete All Attachments checkbox should be used. If a record has multiple attachments with same name, all such matching  attachments will be deleted.',
    category: 'a20738df9363130079b5925cf67ffb74',
    inputs: {
        delete_all_: BooleanColumn({
            label: 'Delete All Attachments?',
            default: true,
        }),
        attachment_file_name: StringColumn({
            label: 'Attachment File Name',
            maxLength: 8000,
        }),
        record: DocumentIdColumn({
            label: 'Source Record',
            mandatory: true,
            default: 'ef43c6d40a0a0b5700c77f9bf387afe3',
            dependent: 'table',
        }),
        table: TableNameColumn({
            label: 'Table',
            mandatory: true,
        }),
    },
    outputs: {},
})
